// Deterministic original synthesized effects. No sampled music, voice or third-party audio.
export function synthGlobeAudio({duration=8,sampleRate=48000,pulses=[1.25,3.1,4.85],lead=6.25}={}){if(!Number.isFinite(duration)||duration<=0||duration>60||sampleRate<8000||sampleRate>96000||!pulses.every(Number.isFinite))throw Error('Invalid sound duration, sample rate or pulses');const count=Math.ceil(duration*sampleRate),stems=Object.fromEntries(['rumble','electric','impact','whoosh'].map(k=>[k,[new Float32Array(count),new Float32Array(count)]]));let seed=9070,low=0,mid=0;const smooth=x=>{x=Math.max(0,Math.min(1,x));return x*x*(3-2*x)};
 for(let i=0;i<count;i++){const t=i/sampleRate,a=t*6.25/lead,fade=smooth(t/.35)*(1-smooth((t-(lead+.45))/.8));seed=(Math.imul(seed,1664525)+1013904223)>>>0;const noise=seed/2147483648-1;low+=.025*(noise-low);mid+=.19*(noise-mid);const rise=smooth((a-3.8)/2.2),whoosh=Math.exp(-Math.pow((a-6.12)/.48,2));let crack=0;for(const p of pulses){const u=a-p;if(u>=0&&u<.3)crack+=(noise*.72+Math.sin(2*Math.PI*(730*u+1700*u*u))*.28)*Math.exp(-u*29)*smooth(u/.002);}const hit=a-5.06,impact=hit>=0?Math.sin(2*Math.PI*(58*hit+20*(1-Math.exp(-hit*7))))*Math.exp(-hit*5)*smooth(hit/.006):0;
  for(let ch=0;ch<2;ch++){const phase=ch*.18;stems.rumble[ch][i]=fade*(.065*Math.sin(2*Math.PI*43*t+phase)+.027*Math.sin(2*Math.PI*67*t)+low*.25);stems.electric[ch][i]=crack*.12*(ch?.9:1);stems.impact[ch][i]=impact*.26;stems.whoosh[ch][i]=((mid-low)*rise*.16+(noise-low)*whoosh*.14)*fade;}}
 const mix=[new Float32Array(count),new Float32Array(count)];for(let ch=0;ch<2;ch++)for(let i=0;i<count;i++){let v=0;for(const stem of Object.values(stems))v+=stem[ch][i];mix[ch][i]=Math.tanh(v)*.8;}return {sampleRate,duration:count/sampleRate,channels:mix,stems};}
export function encodeGlobeWav(channels,sampleRate=48000){const n=channels[0].length,buffer=new ArrayBuffer(44+n*channels.length*2),view=new DataView(buffer);const str=(p,s)=>[...s].forEach((v,i)=>view.setUint8(p+i,v.charCodeAt(0)));str(0,'RIFF');view.setUint32(4,buffer.byteLength-8,true);str(8,'WAVE');str(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,channels.length,true);view.setUint32(24,sampleRate,true);view.setUint32(28,sampleRate*channels.length*2,true);view.setUint16(32,channels.length*2,true);view.setUint16(34,16,true);str(36,'data');view.setUint32(40,n*channels.length*2,true);for(let i=0;i<n;i++)for(let c=0;c<channels.length;c++)view.setInt16(44+(i*channels.length+c)*2,Math.round(Math.max(-1,Math.min(1,channels[c][i]))*32767),true);return new Uint8Array(buffer);}
export function createGlobeSoundPlayer(AudioContextClass=globalThis.AudioContext||globalThis.webkitAudioContext){let context=null,source=null,gain=null,anchor=null,key=null,buffer=null;const stop=()=>{try{source?.stop()}catch{}source=null;anchor=null;};return {stop,async unlock(){if(!AudioContextClass)return false;context??=new AudioContextClass();await context.resume();return context.state==='running';},sync(time,playing,params={},rate=1){if(!context||context.state!=='running'||!playing||!params.globeEnabled||!params.globeSoundEnabled||time<0||time>=params.globeLeadDuration+1.25){stop();return;}const next=JSON.stringify([params.globeLeadDuration,params.globePulseTimes]);if(next!==key){stop();const clip=synthGlobeAudio({duration:params.globeLeadDuration+1.25,lead:params.globeLeadDuration,pulses:params.globePulseTimes});buffer=context.createBuffer(2,clip.channels[0].length,clip.sampleRate);clip.channels.forEach((x,i)=>buffer.copyToChannel(x,i));key=next;}if(anchor===null||anchor.rate!==rate||Math.abs(time-anchor.clip-(context.currentTime-anchor.context)*anchor.rate)>.16){stop();source=context.createBufferSource();source.buffer=buffer;source.playbackRate.value=rate;gain=context.createGain();gain.gain.value=params.globeSoundGain??.55;source.connect(gain);gain.connect(context.destination);source.start(0,Math.min(time,buffer.duration-.001));anchor={clip:time,context:context.currentTime,rate};}else gain.gain.value=params.globeSoundGain??.55;},close(){stop();context?.close();context=null;}};}
